package main

import "fmt"

// UserStore is a port defined where it is consumed.
// The Greeter only needs to look a name up by id.
type UserStore interface {
	Name(id int) (string, bool)
}

// Greeter is the business logic; it depends on the interface.
type Greeter struct {
	store UserStore // injected dependency
}

// NewGreeter is the constructor: dependencies come in as parameters.
func NewGreeter(store UserStore) *Greeter {
	return &Greeter{store: store}
}

func (g *Greeter) Greet(id int) string {
	if name, ok := g.store.Name(id); ok {
		return "Hello, " + name
	}
	return "Hello, stranger"
}

// memStore is one concrete implementation of UserStore.
type memStore map[int]string

func (m memStore) Name(id int) (string, bool) { n, ok := m[id]; return n, ok }

func main() {
	// Composition root: build the concrete dependency and inject it.
	store := memStore{1: "Ada", 2: "Grace"}
	g := NewGreeter(store)
	fmt.Println(g.Greet(1))
	fmt.Println(g.Greet(99))
}

