package main

import (
	"fmt"
	"time"
)

// Clock is a tiny port so time can be injected and controlled.
type Clock interface{ Now() time.Time }

// fixedClock always returns the same instant — perfect for tests.
type fixedClock struct{ t time.Time }

func (f fixedClock) Now() time.Time { return f.t }

type expireService struct {
	clock Clock // injected dependency
}

func NewExpireService(c Clock) *expireService { return &expireService{clock: c} }

func (s *expireService) Deadline(d time.Duration) time.Time {
	return s.clock.Now().Add(d) // uses the injected clock, not time.Now()
}

func main() {
	// Inject a fixed clock so the output is deterministic.
	epoch := time.Date(2020, 1, 1, 0, 0, 0, 0, time.UTC)
	s := NewExpireService(fixedClock{t: epoch})
	fmt.Println(s.Deadline(time.Hour).UTC())
}

