package session

import "time"

// Clock is an injectable port over the current time.
type Clock interface{ Now() time.Time }

// RealClock is the production implementation.
type RealClock struct{}

func (RealClock) Now() time.Time { return time.Now() }

type Manager struct {
	clock Clock // injected dependency
}

// NewManager injects the clock (RealClock in main, a fake in tests).
func NewManager(c Clock) *Manager { return &Manager{clock: c} }

func (m *Manager) NewToken(ttl time.Duration) time.Time {
	return m.clock.Now().Add(ttl) // deterministic when a fixed clock is injected
}

// Store is the port: only the methods Counter actually needs.
type Store interface {
	Get(key string) int
	Set(key string, val int)
}

type Counter struct {
	store Store // injected dependency
}

// New performs constructor injection.
func New(store Store) *Counter {
	return &Counter{store: store}
}

// Incr reads, increments, and writes back through the injected store.
func (c *Counter) Incr(key string) int {
	n := c.store.Get(key) + 1
	c.store.Set(key, n)
	return n
}
